namespace PoloOS.Diagnostics.Core;

public sealed record Kwp2000Message(byte Format,byte? Destination,byte? Source,byte Service,IReadOnlyList<byte> Body,byte Checksum)
{
    public string Hex { get { var bytes=new List<byte>{Format}; if(Destination.HasValue){bytes.Add(Destination.Value);bytes.Add(Source!.Value);} if((Format&0x3F)==0)bytes.Add(checked((byte)(Body.Count+1)));bytes.Add(Service);bytes.AddRange(Body);bytes.Add(Checksum);return string.Join(" ",bytes.Select(x=>x.ToString("X2"))); } }
}
public sealed class Kwp2000Dialog
{
    private const byte TesterAddress=0xF1; private readonly KwpCommon _common; private readonly byte _controllerAddress; private byte _targetAddress; private readonly DiagLog _log;
    public int P3Milliseconds{get;set;}=55; public int P4Milliseconds{get;set;}=5;
    public Kwp2000Dialog(KwpCommon common,byte controllerAddress,DiagLog log,byte? targetAddress=null){_common=common;_controllerAddress=controllerAddress;_targetAddress=targetAddress??controllerAddress;_log=log;}
    public byte TargetAddress {get=>_targetAddress;set=>_targetAddress=value;}
    public Kwp2000Message SendReceive(byte service,params byte[] body){SendMessage(service,body);while(true){var message=ReceiveMessage();if(message.Source.HasValue&&(message.Source!=_targetAddress||message.Destination!=TesterAddress))throw new InvalidOperationException($"KWP2000 address mismatch src={message.Source:X2} dest={message.Destination:X2} expectedSrc={_targetAddress:X2}");if(message.Service==0x7F){if(message.Body.Count>=2&&message.Body[0]==service&&message.Body[1]==0x78){_log.Write($"KWP2000_RESPONSE_PENDING service={service:X2}");continue;}var requested=message.Body.Count>0?message.Body[0]:(byte)0;var reason=message.Body.Count>1?message.Body[1]:(byte)0;throw new InvalidOperationException($"KWP2000 negative response requested={requested:X2} reason={reason:X2}");}if(message.Service!=(byte)(service+0x40))throw new InvalidOperationException($"KWP2000 expected service {(byte)(service+0x40):X2}, got {message.Service:X2}");return message;}}
    public IReadOnlyList<DtcEntry> ReadStoredFaultCodes(){var response=SendReceive(0x18,0x02,0xFF,0x00);return ParseDtcResponse(response);} public IReadOnlyList<DtcEntry> ReadStoredFaultCodesWithSessionFallback(){try{return ReadStoredFaultCodes();}catch(TimeoutException){_log.Write("KWP2000_DIRECT_DTC_TIMEOUT; trying StartDiagnosticSession 10 89");_=SendReceive(0x10,0x89);return ReadStoredFaultCodes();}}
    private static IReadOnlyList<DtcEntry> ParseDtcResponse(Kwp2000Message response){if(response.Body.Count==0)return Array.Empty<DtcEntry>();var count=response.Body[0];var result=new List<DtcEntry>();var pos=1;for(var i=0;i<count&&pos+2<response.Body.Count;i++){var hi=response.Body[pos++];var lo=response.Body[pos++];var status=response.Body[pos++];result.Add(new DtcEntry((hi<<8)|lo,status));}return result;}
    public void SendMessage(byte service,IReadOnlyList<byte> body){var payloadLength=body.Count+1;if(payloadLength>63)throw new ArgumentOutOfRangeException(nameof(body));var bytes=new List<byte>{checked((byte)(0x80|payloadLength)),_targetAddress,TesterAddress,service};bytes.AddRange(body);byte checksum=0;foreach(var b in bytes)checksum=unchecked((byte)(checksum+b));bytes.Add(checksum);PreciseDelay.Milliseconds(P3Milliseconds);for(var i=0;i<bytes.Count;i++){_common.WriteByte(bytes[i]);if(i+1<bytes.Count)PreciseDelay.Milliseconds(P4Milliseconds);}_log.Write($"KWP2000_TX target={_targetAddress:X2} {string.Join(" ",bytes.Select(x=>x.ToString("X2")))}");}
    public Kwp2000Message SendReceiveUnaddressed(byte service,params byte[] body){SendMessageUnaddressed(service,body);while(true){var message=ReceiveMessage();if(message.Service==0x7F){if(message.Body.Count>=2&&message.Body[0]==service&&message.Body[1]==0x78){_log.Write($"KWP2000_RESPONSE_PENDING service={service:X2}");continue;}return message;}return message;}}
    public void SendMessageUnaddressed(byte service,IReadOnlyList<byte> body){var payloadLength=body.Count+1;if(payloadLength>63)throw new ArgumentOutOfRangeException(nameof(body));var bytes=new List<byte>{checked((byte)payloadLength),service};bytes.AddRange(body);byte checksum=0;foreach(var b in bytes)checksum=unchecked((byte)(checksum+b));bytes.Add(checksum);PreciseDelay.Milliseconds(P3Milliseconds);for(var i=0;i<bytes.Count;i++){_common.WriteByte(bytes[i]);if(i+1<bytes.Count)PreciseDelay.Milliseconds(P4Milliseconds);}_log.Write($"KWP2000_TX_UNADDRESSED {string.Join(" ",bytes.Select(x=>x.ToString("X2")))}");}
    public Kwp2000Message ReadIdentification91()=>SendReceive(0x1A,0x91);
    public Kwp2000Message ReceiveMessage(){var format=_common.ReadByte(3000);byte? destination=null,source=null;if((format&0x80)!=0){destination=_common.ReadByte(1500);source=_common.ReadByte(1500);}int length=format&0x3F;if(length==0)length=_common.ReadByte(1500);if(length<1)throw new InvalidOperationException($"Invalid KWP2000 length {length}.");var service=_common.ReadByte(1500);var body=new List<byte>();for(var i=0;i<length-1;i++)body.Add(_common.ReadByte(1500));var checksum=_common.ReadByte(1500);var checkBytes=new List<byte>{format};if(destination.HasValue){checkBytes.Add(destination.Value);checkBytes.Add(source!.Value);}if((format&0x3F)==0)checkBytes.Add(checked((byte)length));checkBytes.Add(service);checkBytes.AddRange(body);byte calculated=0;foreach(var b in checkBytes)calculated=unchecked((byte)(calculated+b));if(calculated!=checksum)throw new InvalidOperationException($"KWP2000 checksum expected {calculated:X2}, got {checksum:X2}.");var message=new Kwp2000Message(format,destination,source,service,body,checksum);_log.Write($"KWP2000_RX {message.Hex}");return message;}
}
